TP.register({id:"lp2-g6",lp:2,grade:"6",mode:"curriculum",checks:1,nextGrade:"7th grade",build(E){const F=E.F;const ico=(n,s=72)=>F.icon(n,s);const STORY_TITLE="The Slow Tree";const STORY=["Imani liked things that finished fast: sprints, pop quizzes, microwave popcorn. So when Mr. Halvorsen handed her a twig no longer than a pencil, she frowned.","“This is a tree?” she asked.","“It is a promise of one,” he said. The old orchard keeper’s hands were as rough as bark, but they moved like a surgeon’s. He sliced the twig at a slant, fitted it against a cut in a young rootstock, and wrapped the joint with tape. “The twig comes from my best Gravenstein. The roots come from a tougher tree. Join them, and you get the best of both.”","“When do we get apples?”","“Three years. Maybe four.”","Imani’s shoulders dropped. Three years was forever. She would be in high school by then. She glanced down the row, where the old trees stood heavy with fruit, and something snagged in her mind.","“Who grafted those?”","“My teacher did, before I was your age,” Mr. Halvorsen said. “I have eaten her apples for sixty years. She never tasted most of them.”","Imani was quiet. The wind moved through the leaves. Then she picked up a second twig and held out her hand for the knife.","“Slow down,” he said, smiling. “Slant cut. Let the green edges touch.”","Her first cut was crooked. Her second was better. She pressed the pieces together, wound the tape tight, and wrote the date on a tag. Under it, in small letters, she added: For whoever is here."].join("\n\n");const POEM_TITLE="For Later";const POEM=[["Someone set these trees in rows","before my name was known.","Someone knelt in April mud","and left the roots alone"],["to do their slow and silent work.","I climb, I pick, I eat.","I never learned the planter’s name.","The fruit is just as sweet."],["So here, this spring, I press a seed","in ground I will not keep.","Let someone, some far summer, find","the shade, and fall asleep."]];const INFO_TITLE="October Apples in May";const INFO=["An apple does not stop living when it is picked. It keeps taking in oxygen and giving off carbon dioxide, a process called respiration. As it breathes, it slowly uses up its own sugars and acids. It also releases ethylene, a gas that tells fruit to ripen. In a kitchen bowl, a crisp apple can turn soft and mealy within a few weeks.","Packing houses slow this process in sealed rooms called controlled atmosphere storage. Workers fill a room with bins of apples, close an airtight door, and change the air inside. Normal air is about 21 percent oxygen. In the storage room, the oxygen is lowered to about 2 percent, and the temperature is held just above freezing. With so little oxygen, the apples breathe very slowly. Some rooms also use filters to remove ethylene.","The results are dramatic. Apples picked in October can come out of storage the following May still firm and juicy. That is why a store can sell apples from nearby orchards long after the trees are bare.","The rooms have limits. Not every variety stores well, and once a room is opened, the apples begin to age at normal speed. The air inside is also dangerous to people. No one may enter until fresh air has been pumped back in."].join("\n\n");const REPORT="This is the Ridgeview Orchard harvest report. Visitors often ask why our 2024 crop was so small. The trees were healthy. The problem was a single night. On April 18, 2024, just after the blossoms opened, the temperature fell to 26 degrees. Open apple blossoms start to die at about 28 degrees, and a dead blossom can never become an apple. In six hours, we lost more than half of that year’s crop. That fall, we bought two wind machines. On cold, still nights, their giant fans pull warmer air down from above the trees. We ran them on four nights this past spring. This fall, the trees gave us the best harvest we have ever measured.";const paras=t=>t.split("\n\n").map(p=>`<p style="margin:0 0 .55em">${p}</p>`).join("");const passage=(text,title)=>`<h3 style="margin:0 0 4px;color:var(--sea);font-size:1.5rem">${title}</h3><div class="passage sm">${paras(text)}</div>`;const poemHtml=()=>`<div class="poem" style="font-size:1.12rem;padding:10px 12px;white-space:normal">${POEM.map(s=>`<p style="margin:0 0 .8em">${s.join("<br>")}</p>`).join("")}</div>`;const checklist=items=>`<ul class="qlist" style="margin-top:12px;font-size:1.3rem">${items.map(x=>`<li style="margin-bottom:6px">${x}</li>`).join("")}</ul>`;const pills=items=>`<div class="row center" style="margin-top:14px;gap:14px;flex-wrap:wrap">${items.map(x=>`<span class="pill" style="font-size:1.25rem">${x}</span>`).join("")}</div>`;const factBox=(title,items)=>`<div style="border:3px solid var(--line);border-radius:16px;padding:10px 18px;margin:14px 0 0;background:var(--surface)"><p class="fig-label" style="margin:0 0 4px;text-align:left;font-size:1.25rem">${title}</p><ul style="margin:0;padding-left:1.2em;font-size:1.25rem;line-height:1.5">${items.map(x=>`<li>${x}</li>`).join("")}</ul></div>`;const card=(head,body)=>`<div style="flex:1 1 250px;border:3px solid var(--line);border-radius:16px;padding:10px 14px;background:var(--surface)"><p class="fig-label" style="margin:0 0 4px;text-align:left;font-size:1.2rem">${head}</p><p style="margin:0;font-size:1.1rem;line-height:1.45">${body}</p></div>`;const svg=(w,h,alt,inner)=>`<svg viewBox="0 0 ${w} ${h}" width="${w}" role="img" aria-label="${alt}">${inner}</svg>`;const pg=(pts,fill)=>`<polygon points="${pts.map(p=>p.join(",")).join(" ")}" fill="${fill||"var(--sea-soft)"}" stroke="var(--ink)" stroke-width="3" stroke-linejoin="round"/>`;const dash=(x1,y1,x2,y2)=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="var(--ink)" stroke-width="2" stroke-dasharray="6 5"/>`;const tx=(x,y,t,a)=>`<text x="${x}" y="${y}" text-anchor="${a||"middle"}" font-size="18" font-weight="700" fill="var(--ink)">${t}</text>`;const ra=(x,y,dx,dy)=>`<path d="M${x+dx} ${y} L${x+dx} ${y+dy} L${x} ${y+dy}" fill="none" stroke="var(--ink)" stroke-width="2"/>`;function plotA(){return svg(250,190,"Right triangle with legs 12 meters and 7 meters",pg([[40,150],[220,150],[40,45]])+ra(40,150,13,-13)+tx(130,175,"12 m")+tx(32,103,"7 m","end"))}function plotB(){return svg(310,200,"Parallelogram with base 9 feet, height 6 feet, and slanted side 7 feet",pg([[40,160],[220,160],[292,40],[112,40]])+dash(112,40,112,160)+ra(112,160,13,-13)+tx(130,185,"9 ft")+tx(120,105,"6 ft","start")+tx(66,95,"7 ft","end"))}function plotC(){return svg(270,190,"Trapezoid with a top of 8 meters, a height of 6 meters, and a bottom split into 3 meters, 8 meters, and 3 meters",pg([[30,150],[240,150],[195,60],[75,60]])+dash(75,60,75,150)+dash(195,60,195,150)+ra(75,150,12,-12)+ra(195,150,-12,-12)+tx(135,50,"8 m")+tx(52,174,"3 m")+tx(135,174,"8 m")+tx(218,174,"3 m")+tx(84,112,"6 m","start"))}function shapesFig(){return`<div class="figure" style="gap:26px;align-items:flex-end">${F.label(plotA(),"Plot A")}${F.label(plotB(),"Plot B")}${F.label(plotC(),"Plot C")}</div>`}function boxSvg(L,W,H,alt){const x=40,y=70,w=200,h=90,dx=64,dy=-40;return svg(350,190,alt,pg([[x,y],[x+dx,y+dy],[x+w+dx,y+dy],[x+w,y]],"var(--surface)")+pg([[x+w,y],[x+w+dx,y+dy],[x+w+dx,y+h+dy],[x+w,y+h]],"var(--gold)")+pg([[x,y],[x+w,y],[x+w,y+h],[x,y+h]])+tx(x+w/2,y+h+24,L)+tx(x-8,y+h/2+6,H,"end")+tx(x+w+dx/2+12,y+h+dy/2+18,W,"start"))}function jugBar(){let s="";for(let i=0;i<8;i++)s+=`<rect x="${20+i*60}" y="44" width="60" height="56" fill="${i<6?"var(--gold)":"var(--surface)"}" stroke="var(--ink)" stroke-width="2.5"/>`+tx(50+i*60,79,"1/8");s+=`<path d="M20 34 v-10 h480 v10" fill="none" stroke="var(--ink)" stroke-width="2"/>`+tx(260,18,"1 gallon")+`<path d="M20 110 v10 h360 v-10" fill="none" stroke="var(--ink)" stroke-width="2"/>`+tx(200,142,"3/4 gallon of cider in the jug (shaded)");return svg(520,150,"A bar split into 8 equal parts. Each part is one eighth. Six parts are shaded to show three fourths of a gallon.",s)}function bedFig(){return svg(330,320,"Rectangle with area five eighths square yard, length three fourths yard, and unknown width",`<rect x="40" y="20" width="234" height="260" fill="var(--sea-soft)" stroke="var(--ink)" stroke-width="3"/>`+tx(157,157,"Area = 5/8 square yard")+tx(157,304,"3/4 yard")+tx(284,157,"?","start"))}function shedFig(){return svg(320,200,"Front view of a shed made of a tall part 8 feet long and 6 feet tall and a short part 4 feet long and 3 feet tall",pg([[40,160],[280,160],[280,100],[200,100],[200,40],[40,40]])+dash(200,100,200,160)+tx(120,184,"8 ft")+tx(240,184,"4 ft")+tx(32,106,"6 ft","end")+tx(288,136,"3 ft","start"))}function dotPlot(o){const W=o.width||560,x0=50,x1=W-50,n=Math.round((o.max-o.min)/o.step);const val=i=>+(o.min+i*o.step).toFixed(4),X=i=>x0+i*(x1-x0)/n;const maxc=Math.max(1,...Object.values(o.counts||{})),H=76+maxc*24;let s=`<svg viewBox="0 0 ${W} ${H+28}" width="${W}" role="img" aria-label="${o.alt||"Dot plot"}">`;s+=`<line x1="${x0-18}" y1="${H-42}" x2="${x1+18}" y2="${H-42}" stroke="var(--fig-ink)" stroke-width="3" stroke-linecap="round"/>`;for(let i=0;i<=n;i++){const v=val(i),x=X(i),c=(o.counts||{})[v]||0;s+=`<line x1="${x}" y1="${H-50}" x2="${x}" y2="${H-34}" stroke="var(--fig-ink)" stroke-width="2.4"/>`;s+=`<text x="${x}" y="${H-10}" font-size="17" text-anchor="middle" fill="var(--ink)">${o.labels&&o.labels[v]||v}</text>`;for(let k=0;k<c;k++)s+=`<circle cx="${x}" cy="${H-60-k*24}" r="8.5" fill="var(--coral)" stroke="var(--fig-ink)" stroke-width="2"/>`}if(o.title)s+=`<text x="${W/2}" y="${H+20}" font-size="17" font-weight="700" text-anchor="middle" fill="var(--ink)">${o.title}</text>`;return s+"</svg>"}const NIGHT_A_TITLE="From a Picker's Notebook";const NIGHT_A="April 18. I went out at dawn because I could not sleep. There was frost on the hood of the truck, and the thermometer by the shed read 26. Mr. Halvorsen was already down the rows, going tree to tree, touching the blossoms with the back of his hand. He did not say anything to me, and I did not ask. The petals that had been white the day before had gone the color of weak tea. I have picked here four autumns. I had never seen him that quiet.";const NIGHT_B_TITLE="Cold Night Cuts the Local Apple Crop";const NIGHT_B="Ridgeview, April 19. The temperature fell to 26 degrees overnight on April 18, below the roughly 28 degree point at which open apple blossoms are killed. Growers in the valley report losing more than half of the expected crop in about six hours. Ridgeview Orchard says it will buy two wind machines, which pull warmer air down over the trees on still, clear nights. Buyers should expect higher prices for local apples this fall.";const WRITE_DIR="Write on your paper. You have about 5 minutes. When you finish, hold it up to the camera or read it to your teacher.";const STOPS=[{id:1,title:"The Slow Tree",short:"Slow Tree",parts:[{std:["RL.6.1"],dur:180,dir:"Read the story to yourself. Then answer out loud. For each answer, read me the exact words from the story that prove it.",desc:"citing evidence from a story for one explicit answer and two inferences",html:()=>passage(STORY,STORY_TITLE),qs:["Why does Mr. Halvorsen join a twig from one tree to the roots of a different tree? Read me the words that tell you.","How does Imani feel when she hears how long the tree will take? The story never names the feeling. Give two details that show it.","At the end, Imani writes “For whoever is here” on the tag. What has she figured out? Which words in the story support your answer?"],key:["To get the strengths of both trees: good fruit and tough roots. Reads “The twig comes from my best Gravenstein. The roots come from a tougher tree. Join them, and you get the best of both.” (RL.6.1, explicit)","Disappointed, let down, or impatient. Two details, such as “Imani’s shoulders dropped,” “Three years was forever,” or that she likes “things that finished fast.” (RL.6.1, inference)","A tree is planted for people who come later, and she may not be the one who eats its apples. Cites “I have eaten her apples for sixty years. She never tasted most of them,” or “Who grafted those?” plus the tag. (RL.6.1, inference)"]}]},{id:2,title:"Power Stack",short:"Powers",parts:[{std:["6.EE.A.1"],dur:100,dir:"Work on your paper. Then tell your teacher each answer.",desc:"writing and evaluating expressions with whole-number exponents",fig:()=>`<div class="figure">${F.label(F.prism(4,4,4,{unit:26}),"A stack of apple crates: 4 long, 4 wide, 4 high")}</div>`,qs:["The stack of crates is 4 crates long, 4 crates wide, and 4 crates high. Write the number of crates using an exponent. Then find its value.","Which is greater, 2<sup>5</sup> or 5<sup>2</sup>? Explain how you know.","Find the error. Kofi says 3<sup>4</sup> = 12. What did Kofi do? What is the correct value?","Find the value of 50 − 2 × 4<sup>2</sup>."],key:["4<sup>3</sup> = 64 crates. 4 × 4 × 4 = 16 × 4 = 64. Or: 4² × 4 = 16 × 4. Partial: the power written right with the value wrong is approaching. (6.EE.A.1, writing a power)","2<sup>5</sup> is greater. 2<sup>5</sup> = 2 × 2 × 2 × 2 × 2 = 32 and 5<sup>2</sup> = 5 × 5 = 25. The student explains by writing out or naming the repeated multiplication. Or: naming the two values straight off, 32 and 25, counts. Partial: the right choice with no reason is approaching. (6.EE.A.1)","Kofi multiplied the base by the exponent (3 × 4). 3<sup>4</sup> means 3 × 3 × 3 × 3 = 81. Partial: 81 given with no account of what Kofi did is approaching. (6.EE.A.1)","18. Exponent first: 4<sup>2</sup> = 16. Then multiply: 2 × 16 = 32. Then subtract: 50 − 32 = 18. Watch for 768, which comes from subtracting first (48 × 16). (6.EE.A.1, order of operations with an exponent)"]}]},{id:3,title:"Sharp Words",parts:[{std:["RL.6.4"],dur:90,dir:"These questions are about words in “The Slow Tree.” Read the story, or look back at it. Then answer out loud.",desc:"figurative and connotative meanings and the effect of a word choice in a story",html:()=>passage(STORY,STORY_TITLE),qs:["The story says Mr. Halvorsen’s hands “were as rough as bark, but they moved like a surgeon’s.” What do these two comparisons tell you about him?","The author calls Mr. Halvorsen an orchard “keeper,” not an orchard “worker.” What extra meaning or feeling does “keeper” carry?","The author wrote that something “snagged in her mind” in place of “she had a thought.” What does “snagged” make you picture? How does that word change the moment?"],key:["His hands are worn and tough from years of outdoor work, yet he is careful, exact, and skilled. Both halves are needed. (RL.6.4, figurative meaning)","“Keeper” suggests someone who guards, cares for, and protects the orchard over a long time, not someone just doing a job. (RL.6.4, connotative meaning)","Something getting caught, like a sleeve on a branch. The thought grabs her suddenly and will not let go. It marks the turn in the story, and the tone shifts from impatient to thoughtful. (RL.6.4, effect of word choice on meaning and tone)"]}]},{id:4,title:"Cider Pour",parts:[{std:["6.NS.A.1"],dur:150,dir:"Work on your paper. Hold it up or tell your teacher each answer.",desc:"dividing fractions with a model, an estimate, and a multiplication check",fig:()=>`<div class="figure">${jugBar()}</div>`,qs:["Use the picture. A jug holds 3/4 gallon of cider. A sample cup holds 1/8 gallon. How many sample cups can the jug fill? Write a division equation that matches.","Estimate first. Without solving, is 7/8 ÷ 1/4 greater than 1 or less than 1? Explain how you know. Then find the exact answer.","Divide: 5/6 ÷ 2/3","Prove your answer to number 3 is right. Use multiplication."],key:["6 cups. 3/4 ÷ 1/8 = 6. In the picture, six 1/8 parts fit in 3/4. Or: 3/4 × 8/1 = 24/4 = 6 without the picture. (6.NS.A.1, visual model)","Greater than 1, because 1/4 fits into 7/8 more than once (7/8 is bigger than 1/4). Exact: 7/8 ÷ 1/4 = 7/8 × 4/1 = 28/8 = 3 1/2. Partial: the estimate right with the exact answer wrong is approaching. (6.NS.A.1, interpreting a quotient)","1 1/4, or 5/4. 5/6 ÷ 2/3 = 5/6 × 3/2 = 15/12 = 5/4. Or: common denominators, 5/6 ÷ 4/6 = 5 ÷ 4 = 1 1/4. (6.NS.A.1, computing a quotient)","Quotient × divisor = the starting number: 5/4 × 2/3 = 10/12 = 5/6. Or: 5/6 ÷ 5/4 = 2/3 returns the divisor and checks it the other way. (6.NS.A.1, relationship between multiplication and division)"]}]},{id:5,title:"Graft and Verse",short:"Story + Poem",parts:[{std:["RL.6.9"],dur:150,dir:"Read the poem to yourself. Look back at the story when you need to. Then answer out loud.",desc:"comparing how a story and a poem approach a similar theme",html:()=>`<style>body:not(.sup-big) .texts article.lookback p{font-size:1.08rem;line-height:1.5}</style><div class="texts" style="grid-template-columns:minmax(0,1.5fr) minmax(0,1fr)"><article class="lookback"><h3>Story: ${STORY_TITLE}</h3>${STORY.split("\n\n").map(p=>`<p style="margin:0 0 .45em">${p}</p>`).join("")}</article><article><h3>Poem: ${POEM_TITLE}</h3>${poemHtml()}</article></div>`,qs:["What theme, or big idea, do the story and the poem share?","How does the story get that idea across? How does the poem do it in a different way? Think about how each one is written.","Look at how each one ends. Name one way the two endings are alike. Use words from both texts."],key:["People plant and do slow work for those who come after them. We enjoy what earlier people planted, and we can pass it on. Any wording close to this. (RL.6.9, shared theme)","Names a real difference in approach. Story: named characters, dialogue, and events in order; Imani changes from impatient to willing, and the idea is shown but never stated. Poem: one speaker who says “I,” short rhyming lines in stanzas, no names and no dialogue; the speaker tells the idea directly. (RL.6.9, contrast in form and approach)","Both end with a gift to an unknown person in the future. Story: the tag that says “For whoever is here.” Poem: “Let someone, some far summer, find the shade.” (RL.6.9, comparison with evidence from both)"]}]},{id:6,title:"Plug It In",parts:[{std:["6.EE.A.2c"],dur:110,dir:"Work on your paper. Hold it up or tell your teacher each answer.",desc:"evaluating expressions and a real-world formula at given values",qs:["Find the value of 4n + 9 when n = 6.","The farm stand uses the formula C = 3.5p + 2. C is the cost in dollars for p pounds of apples plus one bag. Find C when p = 6.","Find the value of 100 − 2y<sup>3</sup> when y = 3.","Find the error. To find 5a<sup>2</sup> when a = 2, Jo wrote (5 × 2)<sup>2</sup> = 100. Is Jo right? Explain how you know."],key:["33. 4 × 6 = 24, then 24 + 9 = 33. Partial: 78 comes from adding before multiplying and does not count. (6.EE.A.2c)","23 dollars. 3.5 × 6 = 21, then 21 + 2 = 23. Partial: 21 leaves the bag out and is approaching. (6.EE.A.2c, formula from a real-world problem)","46. 3<sup>3</sup> = 27, then 2 × 27 = 54, then 100 − 54 = 46. Partial: cubing 2y to get 216 is the error to watch for and does not count. (6.EE.A.2c, exponent in the conventional order)","No. The exponent belongs only to a, so square first: 2<sup>2</sup> = 4, then 5 × 4 = 20. Jo multiplied before squaring. Partial: saying Jo is wrong with no correct value is approaching. (6.EE.A.2c, order of operations)"]}]},{id:7,title:"The Cold Room",short:"Cold Room",parts:[{std:["RI.6.1"],dur:180,dir:"Read the article to yourself. Then answer out loud. For each answer, read me the exact words from the article that prove it.",desc:"citing evidence from an article for one explicit answer and two inferences",html:()=>passage(INFO,INFO_TITLE),qs:["Why does a picked apple turn soft in a kitchen bowl? Read me the words that explain it.","The article says the air in the storage room is dangerous to people, but it does not say why. What can you figure out? Which facts in the article support your answer?","A store near an orchard sells crisp local apples in April. What can you infer about where those apples have been since fall? Give evidence."],key:["It is still alive and breathing, so it uses up its sugars and acids, and ethylene tells it to ripen. Reads “As it breathes, it slowly uses up its own sugars and acids” or “It also releases ethylene, a gas that tells fruit to ripen.” (RI.6.1, explicit)","There is too little oxygen for a person to breathe. Cites “Normal air is about 21 percent oxygen” and “the oxygen is lowered to about 2 percent.” May add “No one may enter until fresh air has been pumped back in.” (RI.6.1, inference)","They were picked in the fall and kept in controlled atmosphere storage. Cites “Apples picked in October can come out of storage the following May still firm and juicy,” and may contrast it with apples going soft “within a few weeks” in a bowl. (RI.6.1, inference)"]}]},{id:8,title:"Orchard Map",parts:[{std:["6.G.A.1"],dur:120,dir:"Work on your paper. Tell your teacher each answer with its units.",desc:"area of a right triangle, a parallelogram, and a trapezoid by breaking shapes apart",fig:()=>shapesFig(),qs:["Plot A is a right triangle. Find its area.","Find the area of Plot B. Which number on the picture did you not need?","Find the area of Plot C. Tell how you broke it into smaller shapes.","A triangle has the same base and the same height as Plot B. What is its area? Explain how you know."],key:["42 square meters. 1/2 × 12 × 7 = 42. Or: 12 × 7 = 84, then halve. Partial: 84 square meters is the whole rectangle and does not count. (6.G.A.1, right triangle)","54 square feet. 9 × 6 = 54. The slanted side, 7 ft, is not needed. Cutting the triangle off one end and sliding it to the other end makes a 9 by 6 rectangle. Partial: using the 7 ft slant to get 63 is the error to watch for and does not count. (6.G.A.1, parallelogram)","66 square meters. Rectangle 8 × 6 = 48. Two triangles, each 1/2 × 3 × 6 = 9. 48 + 9 + 9 = 66. Or: the trapezoid rule, 1/2 × (8 + 14) × 6 = 66. Partial: the rectangle alone, 48, is approaching. (6.G.A.1, decomposing a trapezoid)","27 square feet. A triangle is half of a parallelogram with the same base and height: 54 ÷ 2 = 27, or 1/2 × 9 × 6 = 27. Partial: 54 square feet repeats the parallelogram and does not count. (6.G.A.1)"]}]},{id:9,title:"Frost Report",parts:[{std:["SL.6.2"],dur:150,read:REPORT,dir:"Study the graph. Then listen while your teacher reads a short harvest report. Answer out loud.",desc:"interpreting a graph and a spoken report and explaining what each adds to the topic",html:()=>`<p class="big">Topic: Why does an orchard’s harvest change from year to year?</p>`,fig:()=>`<div class="figure">${F.barGraph({title:"Average bushels of apples per tree",cats:["2022","2023","2024","2025","2026"],vals:[14,15,6,13,16],max:16,step:2})}</div><p class="fig-label" style="text-align:center;margin:0 0 10px">Data from Ridgeview Orchard</p>`,qs:["Look at the graph. Which year stands out? Use numbers to tell how it is different.","Now think about the report. What caused the small crop? What did the orchard do about it?","What does the report add that the graph cannot show? What does the graph add to the report?"],key:["2024. The trees averaged 6 bushels each, less than half of any other year (13 to 16). (SL.6.2, visual and quantitative)","A frost on April 18, 2024. The temperature fell to 26 degrees just after the blossoms opened, and dead blossoms cannot become apples. The orchard bought two wind machines that pull warmer air down on cold nights. (SL.6.2, oral)","The report gives the cause (one frosty night) and the fix (wind machines). The graph shows the size of the drop and the recovery in numbers, and it backs up the report: 6 is less than half of 15, and 16 in 2026 is the highest bar. Needs both directions. (SL.6.2, explains how each contributes to the topic)"]}]},{id:10,title:"Pronoun Pruning",short:"Pronouns",parts:[{std:["L.6.1"],dur:90,dir:"Each cider house note has one pronoun problem. Say the whole sentence the correct way.",desc:"pronoun items on case, intensive pronouns, shifts in person and number, and vague pronouns",qs:["Her and Mr. Diaz pressed forty gallons of cider.","The grower gave Tomas and I the last two crates.","The pickers theirselves sorted every apple by hand.","When a picker climbs a ladder, you should keep one hand on the rail.","Every one of the ladders has their own safety tag.","Rosa told Ms. Bell that she had left the gate open. (Who left it open? Make it clear.)"],key:["She and Mr. Diaz pressed forty gallons of cider. (L.6.1, subject case)","The grower gave Tomas and me the last two crates. (L.6.1, object case)","The pickers themselves sorted every apple by hand. (L.6.1, intensive pronoun)","When a picker climbs a ladder, he or she should keep one hand on the rail. Also correct: “When pickers climb ladders, they should keep one hand on the rail.” (L.6.1, shift in person)","Every one of the ladders has its own safety tag. (L.6.1, shift in number)","Any sentence that makes it clear who left the gate open, such as: Rosa told Ms. Bell, “I left the gate open.” Or: Rosa said that Ms. Bell had left the gate open. (L.6.1, vague pronoun)"]}]},{id:11,title:"Orchard Desk",short:"Write",parts:[{alt:{group:"write",key:"argument",label:"Argue",icon:"💬",hint:"Should the orchard open for U-pick?"},std:["W.6.1"],n:5,label:"checks met",dur:270,dir:WRITE_DIR,desc:"an argument with a claim, reasons, and evidence",html:()=>`<p class="big">Hilltop Orchard might open for U-pick weekends, when visitors pick their own apples. Should it? Write an argument of 5 to 8 sentences. Use at least two facts from the fact box as evidence.</p>${factBox("Fact box: U-pick weekends",["U-pick visitors pay $2.50 a pound. Stores pay the orchard $1.00 a pound.","Visitors drop or waste about 1 of every 10 apples they pick.","The orchard would need 3 extra workers each weekend for parking and ladder safety.","Many visitors also buy cider and pie at the farm stand."])}${checklist(["Make your claim","Give reasons and back them with facts","Link ideas with words like because, for example, as a result","Keep it formal, and end with a conclusion"])}`,key:["Introduces a clear claim: the orchard should or should not open for U-pick (W.6.1)","Gives clear reasons in an order that makes sense (W.6.1)","Supports the reasons with at least two relevant facts from the fact box, such as $2.50 a pound against $1.00, or 1 of every 10 apples wasted (W.6.1)","Uses words, phrases, or clauses that connect the claim and reasons, such as because, for example, as a result (W.6.1)","Keeps a formal style and ends with a concluding statement that follows from the argument (W.6.1)"]},{alt:{group:"write",key:"narrative",label:"Story",icon:"📖",hint:"The tractor will not start"},std:["W.6.3"],n:5,label:"checks met",dur:270,dir:WRITE_DIR,desc:"a narrative with a clear sequence, technique, and descriptive details",html:()=>`<p class="big">It is the last hour of the last day of harvest. One row is still unpicked, and the tractor will not start. Write the scene. It can be real or imagined. Write 5 to 8 sentences.</p>${pills(["Set the scene","The problem","What people do","How it ends"])}${checklist(["Show who is there and where they are","Tell what happens in order","Use dialogue or description","Use time words and exact details the reader can see, hear, or feel","End in a way that fits the story"])}`,key:["Sets up the context and introduces a narrator or characters (W.6.3)","Events unfold in a natural, logical sequence (W.6.3)","Uses a narrative technique such as dialogue, pacing, or description to develop events or characters (W.6.3)","Uses transition words for time or place, precise words, and sensory details (W.6.3)","Provides a conclusion that follows from the events (W.6.3)"]}]},{id:12,title:"Fair Split",parts:[{std:["6.NS.A.1"],dur:180,dir:"Work on your paper. Hold it up or tell your teacher each answer.",desc:"fraction division word problems, a story context, and an error to explain",fig:()=>`<div class="figure">${F.label(bedFig(),"Seedling bed for number 2")}</div>`,qs:["A crew has 4 1/2 pounds of grafting wax. Each bundle of grafts needs 3/4 pound. How many bundles can the crew seal?","A rectangular seedling bed has an area of 5/8 square yard. It is 3/4 yard long. How wide is it?","Make up an orchard story problem that matches 1/2 ÷ 1/8. Then solve it.","Find the error. Ravi solved 3/5 ÷ 1/2 this way: 5/3 × 1/2 = 5/6. What did Ravi do wrong? What is the correct answer?"],key:["6 bundles. 4 1/2 ÷ 3/4 = 9/2 × 4/3 = 36/6 = 6. Or: count up in 3/4s to 4 1/2, which takes 6 steps. (6.NS.A.1, word problem)","5/6 yard. 5/8 ÷ 3/4 = 5/8 × 4/3 = 20/24 = 5/6. Check: 3/4 × 5/6 = 15/24 = 5/8. Or: common denominators, 5/8 ÷ 6/8 = 5 ÷ 6 = 5/6. (6.NS.A.1, word problem with area)","A story that asks how many 1/8s are in 1/2, such as: A jug has 1/2 gallon of cider. Each cup holds 1/8 gallon. How many cups can it fill? Answer: 4. Partial: a matching story with the wrong answer is approaching, and so is the right answer with a story that does not match. (6.NS.A.1, story context)","Ravi flipped the first fraction. Flip the one you divide by: 3/5 × 2/1 = 6/5 = 1 1/5. A second clue: dividing by 1/2 doubles a number, so the answer has to be more than 3/5. Partial: naming the flip with no corrected answer is approaching. (6.NS.A.1)"]}]},{id:13,title:"Source Sorter",short:"Sources",parts:[{std:["W.6.8"],label:"checks met",dur:110,dir:"Question: Which bees are best at pollinating apple trees? Say 1 out loud. Write 2, 3, and 4 on your paper and hold it up.",desc:"judging sources, paraphrasing, quoting, and listing source information",html:()=>`<div style="display:flex;gap:12px;flex-wrap:wrap;margin-bottom:12px">${card("Source A","Article: “Wild Bees in Apple Orchards.” By Dr. Lena Ortiz, insect scientist. Published by State University Extension, 2024.")}${card("Source B","Web page: “Best Honey Ever! Order Today.” From SweetHive Honey Company. No author. No date.")}${card("Source C","Blog post: “My Backyard Bees.” By a hobby gardener, 2015. It says, “I think honeybees are lazy.”")}</div><div class="passage sm" style="border-left:5px solid var(--gold);padding:8px 16px;background:var(--bg);border-radius:8px;margin-bottom:16px"><strong>From Source A:</strong> Mason bees carry loose, dry pollen on their bellies, so more of it rubs off on each blossom. They also keep working in cool, cloudy weather, when honeybees stay in the hive.</div>`,qs:["Which source is the most credible for facts about bees and apple trees? Which is the least credible? Give a reason for each.","Write one note from the Source A box in your own words. Do not copy its sentences.","Copy one short part of the Source A box as an exact quote. Use quotation marks, and write the author’s last name after it.","List Source A the way you would at the end of a report: author, title, who published it, and the year."],key:["Most credible: Source A. It names an author who is an expert, comes from a university, is recent, and is written to inform. Least credible: Source B, an ad written to sell honey with no author or date. Accept Source C as least with a sound reason (one person’s opinion, old, no evidence). (W.6.8, credibility)","A true paraphrase, such as: Mason bees leave more pollen on flowers because their pollen is loose, and they fly even on cold, gray days. Not the source’s sentences with a word or two changed. (W.6.8, paraphrase without plagiarizing)","Exact words from the box inside quotation marks, with Ortiz named. Example: “They also keep working in cool, cloudy weather” (Ortiz). (W.6.8, quoting and giving credit)","Lena Ortiz, “Wild Bees in Apple Orchards,” State University Extension, 2024. Any order is fine when all four pieces are there. (W.6.8, basic bibliographic information)"]}]},{id:14,title:"Bin Builder",parts:[{std:["6.G.A.2"],dur:120,dir:"Work on your paper. Tell your teacher each answer with its units.",desc:"volume of rectangular prisms with fraction edge lengths, by formula and by packing with cubes",fig:()=>`<div class="figure" style="gap:30px;align-items:flex-end">${F.label(boxSvg("4 ft","3 1/2 ft","2 ft","Apple bin 4 feet long, 3 and one half feet wide, and 2 feet tall"),"Apple bin for number 1")}${F.label(F.prism(3,2,2,{unit:38}),"Gift box for number 2, packed with cubes.<br>Each cube is 1/3 foot on every edge.")}</div>`,qs:["Find the volume of the apple bin.","The gift box is 1 foot long, 2/3 foot wide, and 2/3 foot tall. How many of the small cubes fill it? What is the volume of one small cube? Use those two answers to find the volume of the box.","Multiply the three edge lengths of the gift box. What do you notice?","A cider tank holds 30 cubic feet. Its base is 4 feet by 2 1/2 feet. How tall is the tank? Explain how you know."],key:["28 cubic feet. 4 × 3 1/2 × 2 = 14 × 2 = 28. Or: 4 × 2 = 8 first, then 8 × 3 1/2 = 28. (6.G.A.2, V = lwh with a fraction edge)","12 cubes (3 by 2 by 2). One cube is 1/3 × 1/3 × 1/3 = 1/27 cubic foot. The box is 12 × 1/27 = 12/27 = 4/9 cubic foot. Partial: 12 cubes right with the volume wrong is approaching. (6.G.A.2, packing with unit fraction cubes)","1 × 2/3 × 2/3 = 4/9 cubic foot. It is the same volume as packing with cubes. Partial: the product right with no comment on the two methods agreeing is approaching. (6.G.A.2, shows the two methods agree)","3 feet. The base area is 4 × 2 1/2 = 10 square feet. V = Bh, so 30 = 10 × h and h = 3. Or: 30 ÷ 4 = 7.5, then 7.5 ÷ 2 1/2 = 3. (6.G.A.2, V = Bh in a real-world problem)"]}]},{id:15,title:"Pitch It",parts:[{std:["SL.6.4"],n:5,label:"checks met",dur:90,dir:"Plan for 30 seconds. Then talk for 45 to 60 seconds. Look at the camera and speak clearly.",desc:"presenting a claim and findings out loud in a logical order",html:()=>`<p class="big">The orchard has 2 tons of bruised apples that cannot be sold fresh. What should the orchard do with them? Make a claim. Back it up with findings from the card.</p>${factBox("Findings card: 2 tons of bruised apples",["Press them: they would make about 300 gallons of cider. Cider sells for $8 a gallon. Pressing takes 2 workers for 2 days.","Sell them as animal feed: a rancher pays $40 a ton and hauls them away today.","Compost them: no money now, but the compost feeds next year’s trees."])}${pills(["My claim","Finding 1","Finding 2","So..."])}`,key:["States a clear claim about what to do with the apples (SL.6.4)","Puts ideas in a logical order: claim, findings, closing (SL.6.4)","Uses pertinent facts and details from the card, such as 300 gallons at $8 is $2,400, or feed brings only $80 for 2 tons (SL.6.4)","Keeps eye contact with the camera (SL.6.4)","Speaks with adequate volume and clear pronunciation for 45 to 60 seconds (SL.6.4)"]}]},{id:16,title:"The Same Cold Night",short:"Two Accounts",parts:[{title:"Who Is Telling It",std:["RI.6.6"],n:3,dur:45,dir:"Read both short pieces. Then answer out loud.",desc:"finding an author's purpose and point of view and showing how the writing conveys it",html:()=>`${passage(NIGHT_A,NIGHT_A_TITLE)}${passage(NIGHT_B,NIGHT_B_TITLE)}`,qs:["What is the purpose of the second piece? Point to what in the writing tells you.","What is the point of view in the first piece? How is it conveyed?","The first piece never says how much of the crop was lost. What does that leave out tell you about what its writer cared about?"],key:["To inform readers about the freeze and what it will cost them. The place and date line, the exact temperatures, the phrase growers report, and the closing sentence about prices all point that way (RI.6.6)","A first person eyewitness: someone who was there that morning. Conveyed by I and my, by what the writer saw and could not do anything about, and by the detail of Mr. Halvorsen's silence (RI.6.6)","The writer cared about what the morning was like and about Mr. Halvorsen, not about the size of the loss. A personal account is written to put a reader inside the moment (RI.6.6)"]},{title:"Two Ways to Tell It",std:["RI.6.9"],n:3,dur:45,dir:"Use both pieces. Answer out loud.",desc:"comparing and contrasting how two authors present the same event",html:()=>`<details class="look-back" data-again="1" open><summary>Look back at the two pieces</summary>${passage(NIGHT_A,NIGHT_A_TITLE)}${passage(NIGHT_B,NIGHT_B_TITLE)}</details>`,qs:["Name one fact that is in both pieces.","How does each writer present the night differently? Give one detail from each.","You want to know how many bushels the valley lost. Which piece would you use, and why?"],key:["The date, April 18, or the temperature of 26 degrees. Both are in both pieces (RI.6.9)","The notebook gives one person's morning in order, with what she saw and felt: frost on the truck, petals the color of weak tea, a man who would not speak. The news piece gives numbers and a cause across the whole valley: 26 degrees, the 28 degree point, more than half the crop, six hours. Both a detail from each and a statement of the difference are needed (RI.6.9)","The news piece, because it reports amounts across the valley. The notebook only tells what one picker saw in one orchard and never gives a number for the loss (RI.6.9)"]}]},{id:17,title:"Explain the Freeze",short:"Explain",parts:[{std:["W.6.2"],n:4,label:"checks met",dur:60,dir:WRITE_DIR,desc:"an informative piece that explains a process using facts and precise words",html:()=>`<p class="big">Explain to a reader who knows nothing about orchards how one cold spring night can destroy a year of apples, and what growers do about it. Write 5 to 7 sentences.</p>${factBox("Facts you may use",["Apple trees bloom in spring. Open blossoms start to die at about 28 degrees.","A blossom that dies never becomes an apple.","On April 18, 2024, Ridgeview fell to 26 degrees and lost more than half the crop in about six hours.","On a still, clear night the coldest air sinks to the ground and warmer air sits above the treetops.","A wind machine is a tall fan on a tower that pulls the warmer air down over the trees."])}${checklist(["Open by naming what you are explaining","Group the facts so one idea follows the one before it","Use the exact words: blossom, degrees, wind machine","End with a sentence that closes the explanation"])}`,key:["Introduces the topic and previews what the piece will explain (W.6.2)","Develops it with the facts, organized so the cause comes before the fix (W.6.2)","Uses precise, subject specific wording rather than vague wording such as the cold thing (W.6.2)","Ends with a concluding statement that follows from what was explained (W.6.2)","Copying the fact box line for line is not developing a topic. Look for the student's own sentences."]}]},{id:18,title:"Price per Bushel",short:"Rates",parts:[{std:["6.RP.A.3"],n:3,dur:45,dir:"Solve on your paper. Say your answers out loud.",desc:"unit rate, equivalent ratios, and percent of a quantity",html:()=>`<p class="big" style="text-align:center">A bin of 12 bushels sells for $216.</p>`,qs:["What is the price for one bushel?","At that same rate, what would 7 bushels cost?","The valley expected 2,400 bushels and lost 55 percent of them. How many bushels is that?"],key:["$18 per bushel (216 ÷ 12) (6.RP.A.3)","$126 (7 × 18). Or: halve 216 to $108 for 6 bushels, then add one more at $18. (6.RP.A.3)","1,320 bushels (0.55 × 2,400). Or: 10% is 240, so 50% is 1,200 and 5% is 120. Partial: 1,080 is the 45% left and is approaching. (6.RP.A.3)"]}]},{id:19,title:"Below Freezing",short:"Signed",parts:[{std:["6.NS.C.5","6.NS.C.6"],n:3,dur:45,dir:"Look at the number line. Answer out loud.",desc:"using positive and negative numbers for opposite directions and placing them on a number line",fig:()=>`<div class="figure">${F.numberLine({min:-8,max:8,step:1,labelEvery:2,marks:[-6],width:640})}</div>`,qs:["Freezing is 32 degrees. The low that night was 26 degrees. Write how far it was from freezing as a signed number, and say what the sign means.","The dot is on the number line. What number is it on, and what is its opposite?","A storage room floor sits 3 feet below ground and its loft sits 3 feet above. Write each one as a signed number, and say what 0 stands for."],key:["-6, six degrees below freezing. The minus sign is the direction, below, not the size. Partial: −6 with no account of what the sign means is approaching. (6.NS.C.5)","-6, and its opposite is 6. The two sit the same distance from 0 on opposite sides. Partial: the number right with no opposite named is approaching. (6.NS.C.6)","-3 and +3, and 0 stands for ground level, the point the two are measured from. Partial: both numbers right with no account of 0 is approaching. (6.NS.C.5, 6.NS.C.6)"]}]},{id:20,title:"Crates per Hour",short:"Equation",parts:[{std:["6.EE.C.9"],n:3,dur:45,dir:"Answer out loud. Write the equation and the table on your paper.",desc:"writing an equation for two changing quantities and showing them in a table",html:()=>`<p class="big" style="text-align:center">A picker fills 7 crates every hour.</p>`,qs:["Write an equation that relates the number of hours h to the number of crates c.","Make a table of values for 1, 2, 3, and 4 hours.","Which of the two quantities depends on the other? Say how you know."],key:["c = 7h. Writing h = 7c is the reversal to watch for. Or: c = h × 7 or 7h = c count equally. (6.EE.C.9)","7, 14, 21, 28 crates for 1, 2, 3, 4 hours. Partial: three of the four values right is approaching. (6.EE.C.9)","c depends on h. The number of crates is decided by how long the picker works, not the other way round, so h is the independent variable and c is the dependent one. Partial: naming c as dependent with no reason is approaching. (6.EE.C.9)"]}]},{id:21,title:"Bushels per Tree",short:"Data",parts:[{std:["6.SP.B.5"],n:3,dur:45,dir:"Look at the dot plot. Answer out loud. You may use the calculator.",mats:["a calculator"],desc:"summarizing a numerical data set: how many observations, center, and spread",fig:()=>`<div class="figure">${dotPlot({min:9,max:15,step:1,counts:{9:2,10:2,11:1,12:1,14:1,15:1},title:"Bushels picked from each tree",alt:"A dot plot of bushels picked from each of eight trees"})}</div>`,qs:["How many trees were measured?","What is the mean, and what is the median?","What is the range, and what does it tell you about these trees?"],key:["8 trees (2 + 2 + 1 + 1 + 1 + 1). Partial: 7 trees comes from missing the gap at 13 and does not count. (6.SP.B.5)","The mean is 11.25 bushels (90 ÷ 8) and the median is 10.5 bushels, halfway between the 4th and 5th values, 10 and 11. Partial: one of the mean and the median right is approaching. (6.SP.B.5)","6 bushels (15 - 9). The trees were not all alike: the best one gave 6 more bushels than the weakest, which is more than half of what the weakest gave. Partial: 6 bushels with no account of what it tells you is approaching. (6.SP.B.5)","There is no dot at 13, so a student reading left to right may count 7 values. Check the count first if the mean is off."]}]},{id:22,title:"Inside a Tree",short:"Tree Cells",parts:[{std:["LS1"],n:3,dur:85,dir:"Answer out loud.",desc:"relating plant structures to their functions and to the making of food",html:()=>`<p class="big">An apple tree takes water in through its roots, carries it up the trunk, and makes food in its leaves. Each leaf is packed with cells that hold chloroplasts.</p>
     <div class="figure">${ico("tree",74)}${ico("leaf",74)}${ico("drop",74)}</div>`,qs:["Name the job of the roots, the trunk and the leaves, one each.","What two things does a leaf take in besides water, and what two things does it produce?","A branch is wrapped tightly with wire so nothing can move through it. The leaves above the wire stay green for a while but the fruit on that branch never fills out. Explain why, using what moves through a trunk."],key:["Roots take in water and dissolved minerals and anchor the tree. The trunk supports the tree and carries water up and sugars around. Leaves capture light and make sugar. Partial: two of the three jobs given is approaching, and the trunk is usually the one answered as support alone with nothing said about carrying water and sugars. (LS1)","It takes in carbon dioxide from the air and light energy from the sun, and it produces sugar and oxygen. Partial: carbon dioxide and light named with only one of sugar and oxygen produced is approaching. (LS1)","Sugar made in the leaves travels down through living tissue just under the bark, and the wire crushed that path. Water can still rise through the inner wood, so the leaves survive, but sugar cannot reach the fruit, so the fruit cannot fill. Partial: saying the wire blocked the sugar, with nothing said about water still rising through the inner wood and keeping the leaves green, is approaching. (LS1)"]},{std:["LS1"],n:3,dur:85,dir:"Look at the chart. Answer out loud.",desc:"interpreting data on an organism's response to its environment and on cell growth",html:()=>`<p class="big">Two rows of young trees were given the same water and soil. One row stood in full sun, the other in the shade of a barn.</p>
     <table class="bigTable"><tr><th></th><th>Full sun row</th><th>Shaded row</th></tr>
     <tr><td>New growth in one season</td><td>41 cm</td><td>14 cm</td></tr>
     <tr><td>Leaves counted</td><td>186</td><td>97</td></tr>
     <tr><td>Fruit set</td><td>yes</td><td>none</td></tr></table>
     <div class="figure">${ico("sun",74)}${ico("sprout",74)}</div>`,qs:["The shaded row grew less and set no fruit. Explain the cause using what a leaf needs.","A tree gets bigger over a season. Where does the extra material in the new wood and leaves come from?","What is one change you would make to this comparison to be more certain that light was the cause?"],key:["Less light means less photosynthesis, so the shaded trees made less sugar. Growth and fruit both require stored sugar, so with less of it the tree grows slowly and does not have enough to fill fruit. Partial: saying less light means less sugar, with nothing said about fruit needing that sugar to fill, is approaching. (LS1)","Mostly from carbon dioxide out of the air and water, which the tree builds into sugars and then into wood and leaf tissue, with minerals from the soil. The mass comes from matter the tree took in, not from the soil alone. Partial: answering that the material comes from the soil is approaching, since minerals do come from there, but the bulk of the new wood comes from air and water. (LS1)","Any good control: measure the light reaching each row, make the rows the same age and variety, use more trees in each group, or swap which row is shaded the next season. Partial: naming a change with nothing said about what it would make more certain is approaching. (LS1)"]}]},{id:23,title:"Why the Fruit Matches",short:"Heredity",parts:[{std:["LS3"],n:3,dur:85,dir:"Answer out loud.",desc:"comparing offspring from grafting and from seed to explain inheritance and variation",html:()=>`<p class="big">A grafted tree is made by joining a cutting from one tree onto the roots of another. Every apple from that cutting matches the tree it came from. An apple seed planted in the ground grows into a tree whose fruit is usually different from the apple the seed came out of.</p>
     <div class="figure">${ico("apple",74)}${ico("apple",74)}${ico("sprout",74)}</div>`,qs:["Fruit from a graft matches the parent exactly. Fruit from a seed usually does not. Explain the difference using genes.","A seed forms after pollen from one tree reaches the flower of another. How does that explain the range of fruit a seedling can produce?","A grower finds one seedling with unusually sweet apples and wants a thousand trees exactly like it. Which method should the grower use, and why?"],key:["A graft is a piece of the same plant, so it carries identical genes and produces identical fruit. A seed carries a new combination of genes from two parents, so the tree that grows from it has traits neither parent shows exactly. Partial: saying the graft is the same tree, with nothing said about a seed carrying a new combination from two parents, is approaching. (LS3)","The seed gets gene versions from both the flower’s tree and the pollen’s tree, and which versions it gets is chance, so each seed is a different combination and each seedling can look and taste different. Partial: naming both parent trees with nothing said about which gene versions a given seed happens to get is approaching. (LS3)","Grafting, because it copies the genes exactly, so all thousand trees carry the same traits. Planting its seeds would give a thousand different trees. Partial: choosing grafting with no reason given, or with the reason given as speed rather than identical genes, is approaching. (LS3)"]},{std:["LS3"],n:3,dur:80,dir:"Answer out loud.",desc:"distinguishing inherited from acquired traits and describing the effect of a mutation",html:()=>`<p class="big">Three trees in the orchard are described in the record book. One has deeply red fruit. One lost a branch to a storm and grew lopsided. One bears a single branch whose apples ripen three weeks before the rest of the tree.</p>
     <div class="figure">${ico("apple",74)}${ico("tree",74)}${ico("clock",74)}</div>`,qs:["Which of the three features would be passed on through a graft from that tree, and which would not? Explain.","One branch ripening three weeks early is a change in the instructions in that branch’s cells. What is such a change called?","Would an early ripening branch be useful to a grower? Give one reason it might be and one reason it might not."],key:["Deep red fruit and early ripening would be passed on, because they come from the genes in those cells. The lopsided shape would not, because it was caused by storm damage during the tree’s life and did not change its genes. Partial: sorting all three correctly with nothing said about the storm damage not having changed the genes is approaching. (LS3)","A mutation. It changed the genetic instructions in the cells of that branch, so that branch behaves differently from the rest of the tree. Partial: describing the branch as different or as a sport, without naming it a mutation, is approaching. (LS3)","Useful: fruit reaching market earlier spreads out the harvest and may sell for more. Not useful: it may have smaller or poorer fruit, or ripen before pickers are ready, and one branch does not prove the trait is strong. Partial: one of the two sides given is approaching, and the reason it might not be useful is usually the missing one. (LS3)"]}]},{id:24,title:"Soil, Rain and Frost",short:"Soil",parts:[{std:["ESS2"],n:3,dur:85,dir:"Look at the chart. Answer out loud.",desc:"explaining weathering, erosion and how water moves through soil",html:()=>`<p class="big">Two parts of the orchard were measured after a heavy rain.</p>
     <table class="bigTable"><tr><th></th><th>Bare slope</th><th>Slope with grass between rows</th></tr>
     <tr><td>Water soaking in</td><td>little</td><td>most</td></tr>
     <tr><td>Soil washed to the ditch</td><td>heavy</td><td>almost none</td></tr></table>
     <div class="figure">${ico("rain",74)}${ico("herb",74)}${ico("mountain",74)}</div>`,qs:["Explain why grass between the rows changes both how much water soaks in and how much soil is lost.","The soil in this valley came from rock. Name two processes that turn solid rock into soil.","Where does the water that soaks into the ground go, and how can a tree reach it weeks after the rain?"],key:["Roots hold soil in place and leaves and stems slow the water, so it has time to soak in instead of running off. Running water is what carries soil away, so slowing it reduces both runoff and erosion. Partial: accounting for the soil being held in place, with nothing said about the water being slowed so it has time to soak in, is approaching. (ESS2)","Any two: freezing and thawing water cracking rock, roots widening cracks, chemical weathering by water and acids, and abrasion as moving water or wind grinds pieces together. Dead plants and animals add the organic part. Partial: one process named where two were asked for is approaching. (ESS2)","It infiltrates into spaces between soil grains and in rock below, becoming groundwater. Roots reach into that moist soil and draw it up, which is why a tree can survive a dry spell after a wet one. Partial: saying the water goes underground, with nothing said about roots drawing it back out of the moist soil weeks later, is approaching. (ESS2)"]},{std:["ESS2"],n:3,dur:85,dir:"Answer out loud.",desc:"explaining frost, air masses and local weather in a valley",html:()=>`<p class="big">On a still clear night the orchard floor can be several degrees colder than the hillside above it. Frost settles in the low rows first.</p>
     <div class="figure">${ico("snowflake",74)}${ico("thermometer",74)}${ico("wind",74)}</div>`,qs:["Cold air collects on the orchard floor on a still night. Explain why, using what you know about cold air.","Frost is less likely on a cloudy night than on a clear one. Explain the difference.","A grower runs large fans on cold still nights. Using what you said in the first answer, explain how fans could help."],key:["Cold air is denser than warm air, so it sinks and pools in the lowest ground, while warmer air sits above it. On a still night nothing mixes the layers, so the low rows get the coldest air. Partial: saying cold air sinks, with nothing said about it being denser than the warm air above it, is approaching. (ESS2)","Clouds absorb and send back energy radiated from the ground, which slows the loss of heat to the sky. A clear night lets that energy escape, so the ground and the air just above it cool much faster. Partial: saying clouds keep the warmth in like a blanket, with nothing said about energy radiated from the ground being sent back, is approaching. (ESS2)","The fans mix the layers, pulling warmer air from above down into the cold pool, which raises the temperature at the trees enough to prevent frost. It works only when there is a warmer layer above. Partial: saying the fans move the air about, with nothing said about bringing the warmer layer above down to the trees, is approaching. (ESS2)"]}]},{id:25,title:"Water, Pests and Choices",short:"Choices",parts:[{std:["ESS3"],n:3,dur:85,dir:"Look at the chart. Answer out loud.",desc:"evaluating water use and the effects of farming choices on an area",html:()=>`<p class="big">Two orchards draw irrigation water from the same underground supply.</p>
     <table class="bigTable"><tr><th></th><th>Orchard 1</th><th>Orchard 2</th></tr>
     <tr><td>Watering method</td><td>sprinklers at midday</td><td>drip lines at night</td></tr>
     <tr><td>Water used per tree</td><td>240 liters a week</td><td>95 liters a week</td></tr>
     <tr><td>Fruit per tree</td><td>about the same</td><td>about the same</td></tr></table>
     <div class="figure">${ico("drop",74)}${ico("sun",74)}${ico("tree",74)}</div>`,qs:["Orchard 2 uses far less water for the same fruit. Give two reasons its method wastes less.","Both orchards draw from the same underground supply. What happens to that supply if both take more each year than the rain replaces?","Groundwater is called renewable, and yet it can run out. Explain how both of those can be true."],key:["Drip lines put water at the roots instead of spraying it over leaves and bare ground, and watering at night means much less evaporates before the soil takes it up. Midday sprinkling loses water to the air. Partial: one of the two reasons given is approaching, and the night watering is usually the one left out. (ESS3)","The level falls year after year, wells have to be drilled deeper, and eventually the supply cannot meet the demand. Some ground can also settle as water is removed. Partial: saying the supply runs low, with nothing said about wells having to go deeper or the supply failing to meet demand, is approaching. (ESS3)","It is replaced by rain soaking in, which makes it renewable, but replacement is slow, so if water is withdrawn faster than it refills the store shrinks. Renewable means replaced over time, not unlimited. Partial: saying rain refills it, with nothing said about the refilling being slower than the withdrawal, is approaching. (ESS3)"]},{std:["ESS3"],n:3,dur:85,dir:"Answer out loud.",desc:"weighing effects of a farming practice and the use of monitoring data",html:()=>`<p class="big">A pest insect is eating into the fruit. One grower sprays the whole orchard on a fixed schedule. Another sets traps, counts the insects each week, and sprays only when the count rises above a set number.</p>
     <div class="figure">${ico("ladybug",74)}${ico("butterfly",74)}${ico("bee",74)}</div>`,qs:["Give one advantage of spraying only when the counts are high, for the grower and for the surrounding area.","Spraying also kills bees and ladybugs. Why does that matter to an orchard that depends on fruit?","Name one thing counting insects every week tells a grower that a fixed spraying schedule cannot."],key:["For the grower: less spray bought and less labor. For the area: less chemical reaching the soil, the ditch and insects that are not pests. Partial: an advantage for the grower given with nothing said about the surrounding area, or the other way round, is approaching. (ESS3)","Bees pollinate the flowers, and without pollination there is no fruit, while ladybugs eat the pest insects. Killing them removes both the pollination the crop needs and a natural control on the pest. Partial: naming the bees and pollination with nothing said about the ladybugs eating the pests is approaching. (ESS3)","When the pest is actually present and whether it is increasing, so spraying happens at the moment it will do good. A schedule sprays whether or not the pest is there. Partial: saying the counts show how many pests there are, with nothing said about that telling the grower when spraying will do good, is approaching. (ESS3)"]}]},{id:26,title:"Energy in the Orchard",short:"Energy",parts:[{std:["PS3"],n:3,dur:85,dir:"Answer out loud. You may use your paper.",desc:"relating stored energy to height and mass and following an energy transfer",html:()=>`<p class="big">An apple hangs on a high branch. Another hangs on a low branch. Both fall.</p>
     <div class="figure">${ico("apple",74)}${ico("tree",74)}</div>`,qs:["Which apple has more stored energy before it falls, and what two quantities decide the amount?","Describe what happens to that stored energy as the apple falls, and what it has turned into just before the apple lands.","A small apple and a large apple fall from the same branch. Which lands with more kinetic energy, and why?"],key:["The one on the high branch, assuming equal size. Gravitational potential energy depends on mass and on height above the ground. Partial: choosing the high apple with only one of mass and height named is approaching. (PS3)","The stored energy is transferred to kinetic energy as the apple speeds up, so by the moment before it lands nearly all of it is kinetic, with a little lost to the air. Partial: saying the apple speeds up, without naming the stored energy being transferred to kinetic energy, is approaching. (PS3)","The large one, because it has more mass and both reach about the same speed falling from the same height, and kinetic energy depends on mass as well as speed. Partial: choosing the large apple with nothing said about both reaching about the same speed is approaching. (PS3)"]},{std:["PS3"],n:3,dur:85,dir:"Look at the chart. Answer out loud.",desc:"explaining thermal energy transfer and insulation using storage data",html:()=>`<p class="big">Apples were stored three ways and the temperature inside each store was recorded at noon.</p>
     <table class="bigTable"><tr><th>Store</th><th>Temperature inside</th></tr>
     <tr><td>open crate in the barn</td><td>18 °C</td></tr>
     <tr><td>crate wrapped in straw</td><td>12 °C</td></tr>
     <tr><td>cellar below ground</td><td>7 °C</td></tr></table>
     <div class="figure">${ico("box",74)}${ico("thermometer",74)}${ico("wheat",74)}</div>`,qs:["Explain how straw around a crate keeps the apples cooler through a warm day.","The cellar is coldest without any machine. Explain where the warm air’s energy goes.","Apples last longer when they are cold. Using energy ideas, explain why keeping something cold means keeping energy out rather than putting cold in."],key:["Straw traps air and conducts poorly, so thermal energy from the warm barn air moves slowly through it. The apples still warm up, just much more slowly. Partial: saying the straw keeps the heat out, with nothing said about it being a poor conductor so the energy moves slowly, is approaching. (PS3)","Thermal energy moves from the warmer air into the cooler ground and stone, which has a great deal of mass and stays near the same temperature all year, so the cellar air stays cool. Energy always moves from warmer to cooler. Partial: saying the ground is cold, with nothing said about energy moving from the warmer air into the cooler stone, is approaching. (PS3)","Cold is not a substance that can be added. Temperature falls when thermal energy leaves and stays low when little energy comes in, so insulation and underground storage work by slowing the transfer of energy inward. Partial: saying the cellar keeps the cold in is the misconception this question is after and is approaching only if the answer also says temperature falls when energy leaves. (PS3)"]}]},{id:27,title:"Protecting the Crop",short:"Design",parts:[{std:["ETS1"],n:3,dur:85,dir:"Answer out loud. Write the criteria and constraints on your paper.",desc:"defining a design problem with measurable criteria and real constraints",html:()=>`<p class="big">Birds are taking fruit from the trees nearest the fence. The grower has netting, poles, old pie tins, string and two afternoons. Pickers must still be able to reach every tree, and nothing may hurt the birds.</p>
     <div class="figure">${ico("bluebird",74)}${ico("apple",74)}${ico("topHat",74)}</div>`,qs:["State the problem in one sentence that names the need without naming a device.","Write two criteria that could be measured and two constraints from the description.","Why does the rule that pickers must still reach every tree count as a constraint rather than a criterion?"],key:["Something like: keep birds from eating fruit on the trees by the fence without harming the birds. It names the need and the limit, not the solution. Partial: a sentence that names netting or tins rather than the need is approaching. (ETS1)","Criteria: fruit lost drops below some number, it works for the whole picking season, it covers all the fence row trees. Constraints: only the materials listed, two afternoons, pickers must still have access, no harm to birds. Partial: two criteria and one constraint, or one of each, is approaching. (ETS1)","Because it is a limit the solution cannot break, not a measure of how well the solution solves the bird problem. A criterion measures success; a constraint bounds what is allowed. Partial: calling it a rule or a condition, with nothing said about the difference between a limit and a measure of success, is approaching. (ETS1)"]},{std:["ETS1"],n:3,dur:85,dir:"Look at the test results. Answer out loud.",desc:"comparing tested designs against criteria and choosing what to improve",html:()=>`<p class="big">Three ideas were tried on four trees each for one week.</p>
     <table class="bigTable"><tr><th>Idea</th><th>Fruit lost</th><th>Picker access</th><th>Time to set up</th></tr>
     <tr><td>A: netting over the whole row</td><td>2 apples</td><td>difficult</td><td>most of two afternoons</td></tr>
     <tr><td>B: hanging pie tins</td><td>26 apples</td><td>easy</td><td>one hour</td></tr>
     <tr><td>C: netting on the outer side only</td><td>7 apples</td><td>easy</td><td>one afternoon</td></tr></table>
     <div class="figure">${ico("bluebird",74)}${ico("box",74)}${ico("clock",74)}</div>`,qs:["Which idea best balances the criteria and the constraints? Use the numbers in your answer.","Idea A loses the least fruit and still should not be chosen. Explain why, using a constraint.","Pick one idea and describe one change you would test next, and say what result would tell you the change worked."],key:["Idea C. It cuts losses from 26 to 7 while keeping access easy and fitting in one afternoon, so it meets the constraints that A breaks. Partial: naming Idea C with no number from the table used to support it is approaching. (ETS1)","It makes picker access difficult, which was a constraint, and it uses nearly all the available time. A design that breaks a constraint is not a solution however well it scores on a criterion. Partial: saying Idea A takes too long, with nothing said about picker access being a constraint it breaks, is approaching. (ETS1)","Any testable change with a stated measure: add tins to the open side of C and see whether losses fall below 7, or raise the netting to improve access and check that losses do not rise. The answer must name what would count as success. Partial: a change named with no result stated that would count as success is approaching. (ETS1)"]}]},{id:28,title:"From Wild Seed to Harvest",short:"Wild Seed",parts:[{std:["HSS-6.1"],n:3,dur:90,dir:"Compare the two sites. Answer out loud.",desc:"using finds from two sites as evidence that people moved from gathering to farming",html:()=>`<p class="big">Diggers compared two village sites in the same valley. The one on the left is older by about two thousand years.</p>
     <table class="bigTable"><tr><th>What was found</th><th>Older site</th><th>Newer site</th></tr>
     <tr><td>Grain</td><td>small grains of many different wild kinds</td><td>larger grains, nearly all one kind</td></tr>
     <tr><td>Animal bones</td><td>wild deer and birds of many ages</td><td>sheep and goats, mostly young animals</td></tr>
     <tr><td>Containers</td><td>a few light baskets</td><td>heavy clay jars and lined storage pits</td></tr></table>
     <div class="figure">${ico("wheat",74)}${ico("sheep",74)}${ico("box",74)}</div>`,qs:["The grain at the newer site is larger and nearly all one kind. What were those people doing that the older group was not?","At the newer site nearly all the sheep and goat bones are from young animals. What does that pattern suggest about how they got meat?","Heavy clay jars and lined pits are hard to move. What does finding many of them suggest about how those people lived?"],key:["Planting and choosing seed. Saving seed from the best plants year after year makes the grain bigger and makes one kind take over, which is farming rather than gathering whatever grew wild. Partial: saying they farmed with no account of saving the best seed is approaching. (HSS-6.1)","They kept a herd and used animals they raised rather than hunting whatever they came across. A hunter takes animals of all ages; a herder keeps breeding females and uses the young. Partial: saying they ate meat with no contrast between a hunter's and a herder's bones is approaching. (HSS-6.1)","They stayed in one place year round. Storage also means they had more food than they needed at once and expected to use it later, which is a settled farming life. Partial: saying they stayed put with nothing said about storing a surplus is approaching. (HSS-6.1)"]},{std:["HSS-6.2"],n:4,dur:100,dir:"Read the note. Answer out loud.",desc:"connecting river farming to specialized work, written law, taxation and trade in Mesopotamia, Egypt and Kush",html:()=>`<p class="big">A clay tablet from a Mesopotamian city lists the people paid from the city’s grain store: farmers, but also potters, metalworkers, weavers, scribes, priests and soldiers. Egyptian officials measured how high the Nile rose, then collected part of each harvest. Kush sent gold, ivory and ebony downriver and received Egyptian grain and crafted goods.</p>
     <div class="figure">${ico("wheat",74)}${ico("coin",74)}${ico("sailboat",74)}</div>`,qs:["How does growing more food than the farmers themselves need make potters, scribes and soldiers possible?","Hammurabi, a Babylonian king, had his laws carved on stone pillars and set up in public. What does putting law in public stone do that a spoken order from a king does not?","Egyptian officials measured the river, then set the tax on the harvest. What does that tell you about the government’s part in the economy?","Kush traded raw materials for Egyptian grain and crafted goods. What does that exchange show about what each economy had and lacked?"],key:["Surplus food can be stored and handed out, so some people can spend their days doing something other than farming and still eat. Specialized work depends on a food surplus somebody else produced. Partial: saying some people did other jobs with no account of who fed them is approaching. (HSS-6.2)","It is fixed, public and the same for everyone who passes it, so it can be pointed to later and does not change with the ruler’s mood or memory. A spoken order is known only to whoever heard it. Partial: saying everyone could see it with nothing said about the law being fixed is approaching. (HSS-6.2)","The government measured, predicted and took a share of production, so it was directly inside the economy rather than standing outside it, and its income rose and fell with the river. Partial: naming the tax with nothing said about the government being inside the economy is approaching. (HSS-6.2)","Kush had raw materials, including gold and later iron, and wanted grain and manufactured goods. Egypt had the farmland and the workshops and wanted the raw materials. Each supplied what the other could not easily get. Partial: one side of the exchange described is approaching. (HSS-6.2)"]}]},{id:29,title:"Fields, Flocks and Fair Measure",short:"Fields",parts:[{std:["HSS-6.3"],n:3,dur:90,dir:"Read the note. Answer out loud.",desc:"analyzing Ancient Hebrew law, land use and belief as parts of one social structure",html:()=>`<p class="big">Judaism, the religion of the Ancient Hebrews, taught belief in one God, and its law and ethical teaching came from the Torah. That law set rules for farming. A farmer was to leave the edges of a field and any fallen fruit for the poor and for strangers passing through. Fields were to be left unplanted every seventh year. Land was meant to stay with the family that held it rather than be sold away for good.</p>
     <div class="figure">${ico("wheat",74)}${ico("apple",74)}${ico("hands",74)}</div>`,qs:["What does a law that reserves part of every harvest for the poor and for strangers tell you about the society that wrote it?","Name one effect of leaving fields unplanted every seventh year on the land. One effect on the people who lived off those fields.","Judaism held that there was one God and that the law in the Torah came from that belief. How does tying law to belief change how binding a law feels?"],key:["That caring for people with no land was treated as an obligation written into law, not a favor, and that strangers were included rather than only their own families. Partial: saying they helped the poor with nothing said about it being written into law is approaching. (HSS-6.3)","On the land: soil that is not cropped every year recovers, so yields hold up. On the people: they had to store enough in advance to live through a year with no harvest, which takes planning and shared stores. Partial: one of the two effects given is approaching. (HSS-6.3)","A law that comes from belief is not only a rule the government can change; breaking it is breaking something the whole people hold to be true, so it binds even when no official is watching. Partial: saying people took it seriously with no account of why belief binds differently is approaching. (HSS-6.3)"]},{std:["HSS-6.4"],n:3,dur:90,dir:"Read the note. Answer out loud.",desc:"connecting Greek soil and crops to trade, colonies, coinage and public life",html:()=>`<p class="big">Greek soil is thin and rocky. Grain grew poorly there, but olive trees and grapevines did well. Greek city-states each struck their own coins, stamped with their own symbol, and traded around the Mediterranean. In the open square of a Greek city, called the agora, people bought food, heard public notices and argued about city business in the same place.</p>
     <div class="figure">${ico("leaf",74)}${ico("coin",74)}${ico("sailboat",74)}</div>`,qs:["Greek land was poor for grain and good for olives and grapes. How would that fact shape what Greeks traded and where they settled?","Each city-state struck its own coins with its own symbol. What does that tell you about Greek political structure?","The same open square served as market and as the place city business was argued. What does that suggest about how an Athenian citizen took part in government?"],key:["They sold what they had, oil and wine, and bought what they lacked, grain, so they became traders and sailors and planted colonies on coasts where grain grew, which spread Greek settlement far from Greece. Partial: naming the olives and grapes with nothing said about buying grain or planting colonies is approaching. (HSS-6.4)","Each city-state was independent and governed itself, with its own money, symbols and decisions. There was no single Greek government over them. Partial: noting the separate coins with nothing said about independent government is approaching. (HSS-6.4)","Taking part was an everyday, in person thing rather than a separate errand: a citizen met the news and the arguments while doing ordinary business, which suited a government in which citizens voted themselves. Partial: saying the square was busy with no link to how a citizen took part is approaching. (HSS-6.4)"]}]},{id:30,title:"Cotton, Silk and Grain",short:"Trade Goods",parts:[{std:["HSS-6.5"],n:3,dur:90,dir:"Read the note. Answer out loud.",desc:"using Indus finds and Indian crops to analyze trade and economic structure",html:()=>`<p class="big">At Indus Valley sites, diggers found sets of small stone weights that match each other closely from city to city. Indus stone seals have turned up in Mesopotamia, far to the west. Indian farmers grew cotton and wove it into cloth that traveled a long way from where it was made. The same routes carried beliefs as well as goods. Two of the world’s major religions began in India: Hinduism, which stayed largely within India, and Buddhism, which traders and travelers carried far beyond it into central, southeast and east Asia.</p>
     <div class="figure">${ico("gem",74)}${ico("map",74)}${ico("scarf",74)}</div>`,qs:["Weights from different Indus cities match each other closely. What does using the same weights across many cities make possible?","An Indus seal was found in Mesopotamia. What does an object from one civilization turning up in another tell you? And according to the note, how did Buddhism reach places far from India?","Cotton can be spun and woven into cloth before it is sold. How does that change what the crop is worth to the region that grows it?"],key:["Honest trade between strangers. If a measure means the same thing in every city, buyers and sellers can agree on an amount without trusting each other, which points to trade managed across a wide area. Partial: saying the weights were the same with nothing said about trade between strangers is approaching. (HSS-6.5)","The two were in contact, directly or through traders in between, so goods and probably ideas moved between them. One object does not prove how often, which is worth saying. On Buddhism: traders and travelers carried it along the same trade routes that carried Indian goods, into central, southeast and east Asia, while Hinduism stayed largely within India. Both halves are needed for full credit. Partial: one half without the other is approaching, so the contact half with nothing on Buddhism sits there. (HSS-6.5)","A region that only sells raw cotton earns once. A region that spins and weaves it sells a finished good worth more, which supports weavers and traders as well as farmers. Partial: saying cloth is worth more with nothing said about who else it supports is approaching. (HSS-6.5)"]},{std:["HSS-6.6"],n:3,dur:90,dir:"Read the note. Answer out loud.",desc:"analyzing Chinese farming regions, silk production and the trade routes west",html:()=>`<p class="big">Northern China grew millet and wheat in dry fields. Southern China grew rice in fields flooded with water. Silk was made from thread spun by silkworms raised on mulberry leaves, and for centuries only China knew how it was done. Chinese goods traveled west along routes later called the Silk Road. Traffic went the other way too: Buddhism traveled east along those routes from India and took root in China, where Confucianism and Daoism were already long established.</p>
     <div class="figure">${ico("wheat",74)}${ico("drop",74)}${ico("scarf",74)}</div>`,qs:["The north grew millet and wheat and the south grew rice in flooded fields. What does that difference tell you about what decided Chinese farming?","For centuries only China knew how silk was made. What does holding the only supply of a wanted product do for a country’s trade?","Goods moved west along the Silk Road, and other things moved east. According to the note, which religion reached China that way, and name one other thing besides goods that a long trade route carries."],key:["Climate and water. Rice needs standing water and a long warm season, millet and wheat do not, so farmers grew what the rainfall and temperature of their own region allowed. Partial: naming the two crops with no reason behind the split is approaching. (HSS-6.6)","China could set the price and trade silk for whatever it wanted, and buyers had to come to it. A product no one can copy gives a lasting advantage rather than a one time sale. Partial: saying silk was valuable with nothing said about holding the only supply is approaching. (HSS-6.6)","Buddhism, which traveled east from India along those routes and took root in China alongside Confucianism and Daoism. For the second half, any one of these counts if the student can explain how it would travel with traders: ideas, technology, languages, news, art styles, disease. Both halves are needed for full credit. Partial: one half without the other is approaching, so Buddhism named with nothing else a route carries sits there. (HSS-6.6)"]},{std:["HSS-6.7"],n:3,dur:140,dir:"Read the note. Answer out loud.",desc:"analyzing Rome's grain supply, estates and written law",html:()=>`<p class="big">The city of Rome grew far too large to be fed by the farms around it, so grain came by ship from Egypt and North Africa. In the countryside, wealthy Romans bought up large estates worked by enslaved people, and many plebeian families lost their small farms. Rome’s earliest written laws, the Twelve Tables, were set up in the forum where anyone could see them. Roman law kept changing long after that. Christianity began in the Roman province of Judea with the teachings of Jesus of Nazareth, and spread through the crowded cities the grain ships supplied. For nearly three centuries Roman law outlawed the practice, and Christians who would not give it up were persecuted: they lost property, were put on trial and some were put to death. In 313 the emperor Constantine made it legal, and before the end of that century it had become the official religion of the empire.</p>
     <div class="figure">${ico("sailboat",74)}${ico("wheat",74)}${ico("board",74)}</div>`,qs:["Rome depended on grain shipped in from provinces across the sea. What risk does that dependence create for the city?","Large estates grew while small plebeian farms disappeared. What does that change do to the social structure of the republic?","Why would plebeians have pushed for the laws to be written down and posted in public? And according to the note, how did Roman law's treatment of Christianity change over time?"],key:["Anything that stops the ships stops the food: a storm season, a bad harvest in Egypt, a lost province, or a fleet held up. A city that cannot feed itself can be pressured through its food supply. Partial: saying it was risky with no example of what could stop the ships is approaching. (HSS-6.7)","Wealth and land concentrate at the top while ordinary farming families lose their independence and move to the city looking for work, so the gap between patrician wealth and plebeian poverty widens and more people depend on others for food and work. Partial: noting the big estates with nothing said about what happened to the farming families is approaching. (HSS-6.7)","Unwritten law was interpreted by patrician officials, so plebeians could not tell whether a ruling matched what had been done before. Posted law can be read, quoted and checked, which limits what an official can simply declare. On Christianity: for nearly three centuries Roman law outlawed the practice and persecuted Christians who would not give it up, Constantine made it legal in 313, and before the end of that century it had become the empire's official religion. Three stages: outlawed, then legal, then official. Both halves are needed for full credit. Partial: one half without the other is approaching, so the plebeian reason with nothing on Christianity sits there. (HSS-6.7)"]}]}];const LEVELUPS={1:{id:"L1",title:"Level Up: Three Proofs",std:["RL.7.1"],needs:["RL.6.1"],n:2,dir:"Answer out loud. Use the story.",html:()=>`<ol class="qlist"><li>Imani changes during this story. Tell how she changes.</li><li>Prove it with at least three pieces of evidence: one from the beginning, one from the middle, and one from the end.</li></ol>${passage(STORY,STORY_TITLE)}`,key:["She goes from wanting fast results to choosing slow work that will help someone else later. (RL.7.1, analysis)","Three or more pieces from different parts. Beginning: she “liked things that finished fast,” she frowned, her shoulders dropped, “Three years was forever.” Middle: something “snagged in her mind,” she asks “Who grafted those?” and then is quiet. End: she picks up a second twig, tries again after a crooked cut, and writes “For whoever is here.” (RL.7.1, several pieces of evidence)"]},10:{id:"L10",title:"Level Up: Misplaced Parts",std:["L.7.1"],needs:["L.6.1"],n:3,dir:"Say each sentence the correct way.",html:()=>`<ol class="qlist"><li>This sentence sounds like a hawk is on the ladder. Fix it: The picker saw a hawk climbing the ladder.</li><li>This sentence sounds like the apples are walking. Fix it: Walking through the orchard, the apples looked ripe.</li><li>Join these into one sentence that starts with Because, Although, or When: The frost came early. The crew picked all night.</li></ol>`,key:["Climbing the ladder, the picker saw a hawk. Or: While the picker was climbing the ladder, she saw a hawk. (L.7.1, misplaced modifier)","Adds who was walking, such as: Walking through the orchard, we saw that the apples looked ripe. (L.7.1, dangling modifier)","Because the frost came early, the crew picked all night. Also correct: When the frost came early, the crew picked all night. (L.7.1, complex sentence with a dependent clause)"]},12:{id:"L12",title:"Level Up: Cold Room Math",std:["7.NS.A.3"],needs:["6.NS.A.1"],n:3,dir:"Work on your paper. Tell your teacher each answer.",html:()=>`<p class="big">Workers are cooling a storage room. Its temperature changes by −1 1/2 degrees each hour.</p><ol class="qlist"><li>What is the total change after 2 1/2 hours?</li><li>How many hours does it take for a total change of −6 degrees?</li><li>The room starts at 38 1/4 degrees. What is the temperature after 2 1/2 hours?</li></ol>`,key:["−3 3/4 degrees. −1 1/2 × 2 1/2 = −3/2 × 5/2 = −15/4. (7.NS.A.3)","4 hours. −6 ÷ (−1 1/2) = 6 ÷ 3/2 = 6 × 2/3 = 4. (7.NS.A.3)","34 1/2 degrees. 38 1/4 − 3 3/4 = 34 2/4 = 34 1/2. (7.NS.A.3)"]},14:{id:"L14",title:"Level Up: Shed Space",std:["7.G.B.6"],needs:["6.G.A.2"],n:3,dir:"Work on your paper. Tell your teacher each answer with its units.",html:()=>`<div class="figure"><div style="text-align:center">${shedFig()}<p class="fig-label">Front view of a storage shed. The whole shed is 5 feet deep from front to back.</p></div></div><ol class="qlist"><li>The shed is made of two rectangular prisms. Find the volume of the whole shed.</li><li>Find the area of the shed’s floor.</li><li>One can of floor sealer covers 25 square feet. How many cans are needed for the floor?</li></ol>`,key:["300 cubic feet. Tall part: 8 × 5 × 6 = 240. Short part: 4 × 5 × 3 = 60. 240 + 60 = 300. (7.G.B.6, volume of a composed solid)","60 square feet. The floor is 12 feet by 5 feet, or 8 × 5 + 4 × 5 = 40 + 20. (7.G.B.6, area)","3 cans. 60 ÷ 25 = 2.4, so 2 cans are not enough. (7.G.B.6, real-world problem)"]}};const READ_STD=["RL.6.1","RL.6.4","RL.6.9","RI.6.1","RI.6.6","RI.6.9","RL.7.1"];const WRITE_STD=["W.6.1","W.6.2","W.6.3"];const MATH_STD=["6.EE.A.1","6.EE.A.2c","6.NS.A.1","6.G.A.1","6.G.A.2","6.RP.A.3","6.NS.C.5","6.NS.C.6","6.EE.C.9","6.SP.B.5","7.NS.A.3","7.G.B.6"];const dlist=rows=>`<dl style="margin:0;font-size:1.15rem;line-height:1.45">${rows.map(r=>`<dt style="font-weight:700">${r[0]}</dt><dd style="margin:0 0 8px 1em">${r[1]}</dd>`).join("")}</dl>`;const ul=items=>`<ul style="margin:6px 0 0;padding-left:1.2em;font-size:1.1rem;line-height:1.45">${items.map(x=>`<li>${x}</li>`).join("")}</ul>`;const G_STORY=[["rootstock","the roots and lower trunk of a young tree that a cutting is joined to"],["Gravenstein","a kind of apple"],["slant","at an angle, not straight across"],["grafted","joined a cutting from one tree onto another tree so they grow as one"]];const G_POEM=[["knelt","got down on the knees"],["planter","the person who planted something"]];const G_INFO=[["mealy","soft, dry, and crumbly"],["airtight","sealed so that no air can get in or out"],["packing house","a building where fruit is sorted, stored, and boxed"],["variety","a kind or type"],["dramatic","big and easy to notice"]];const G_FROST=[["bushel","a measure for fruit. A bushel of apples weighs about 42 pounds."],["blossom","the flower of a fruit tree"],["average","the usual amount: the total shared out equally"]];const G_NIGHT=[["thermometer","a tool that measures temperature"],["blossom","the flower of a fruit tree"],["bushel","a measure for fruit. A bushel of apples weighs about 42 pounds."],["wind machine","a tall fan on a tower that pulls warmer air down over an orchard"]];const G_SRC=[["credible","able to be trusted"],["paraphrase","to say it in your own words"],["quote","the exact words from a source, inside quotation marks"],["pollinating","carrying pollen from flower to flower so fruit can grow"],["extension","the part of a state university that shares farm research with the public"]];function glossHtml(st){const s=st.std;if(s.includes("RL.6.9"))return dlist(G_POEM.concat(G_STORY));if(s.includes("RI.6.1"))return dlist(G_INFO);if(s.includes("SL.6.2"))return dlist(G_FROST);if(s.includes("W.6.8"))return dlist(G_SRC);if(s.includes("RI.6.6")||s.includes("RI.6.9")||s.includes("W.6.2"))return dlist(G_NIGHT);return dlist(G_STORY)}const FR={"RL.6.1":["I think ____. The words that prove it are “____.”","The story says, “____.” This shows that ____."],"RL.7.1":["At the start, Imani ____. The story says, “____.”","By the end, she ____. I know because ____."],"RI.6.1":["The article says, “____.” This explains why ____.","I can tell that ____ because the article says “____” and “____.”"],"RL.6.9":["Both the story and the poem are about ____.","The story shows this by ____. The poem shows it by ____."],"SL.6.2":["The graph shows that ____.","The report explains that ____, which the graph cannot show."],"SL.6.4":["I think the orchard should ____.","The first reason is ____.","The card also shows that ____.","So the best choice is ____."],"W.6.1":["Hilltop Orchard should (or should not) ____.","One reason is ____. For example, ____.","Another reason is ____, because ____.","As a result, ____.","For these reasons, ____."],"RI.6.6":["The writer's purpose is ____. I can tell because the piece ____.","The point of view is ____, shown by the words “____.”"],"RI.6.9":["Both pieces say that ____.","The first piece shows the night by ____, while the second shows it by ____."],"W.6.2":["This is how ____ happens.","First, ____. Then ____.","One way growers answer it is ____.","In short, ____."],"W.6.3":["The sun was almost down when ____.","“____,” said ____.","A moment later, ____.","I could hear ____ and smell ____.","In the end, ____."]};function framesHtml(st){const k=st.std.find(x=>FR[x]);return`<ul class="starters">${(FR[k]||[]).map(x=>`<li>${x}</li>`).join("")}</ul>`}const MULT_N=12;let multSel=[0,0];function multHtml(){let h=`<div class="tool-scroll"><table class="mult"><tr><th>×</th>`;for(let c=1;c<=MULT_N;c++)h+=`<th data-r="0" data-c="${c}" class="${multSel[1]===c?"hl":""}">${c}</th>`;h+="</tr>";for(let r=1;r<=MULT_N;r++){h+=`<tr><th data-r="${r}" data-c="0" class="${multSel[0]===r?"hl":""}">${r}</th>`;for(let c=1;c<=MULT_N;c++){const hr=multSel[0]===r,hc=multSel[1]===c;h+=`<td data-r="${r}" data-c="${c}" class="${hr&&hc?"pick":hr||hc?"hl":""}">${r*c}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to light up its row and column. Click it again to clear.</p>`}function multBind(body,r){body.querySelectorAll("[data-r]").forEach(c=>c.onclick=()=>{const x=+c.dataset.r,k=+c.dataset.c;multSel=multSel[0]===x&&multSel[1]===k?[0,0]:[x,k];r()})}let calcE="",calcAns="";function calcEval(){const s=calcE.replace(/×/g,"*").replace(/÷/g,"/").replace(/−/g,"-");let i=0;const num=()=>{if(s[i]==="("){i++;const v=expr();if(s[i]===")")i++;return v}if(s[i]==="-"){i++;return-num()}const m=/^(\d+\.?\d*|\.\d+)/.exec(s.slice(i));if(!m)throw new Error("n");i+=m[0].length;return+m[0]};const term=()=>{let v=num();while(s[i]==="*"||s[i]==="/"){const o=s[i++],x=num();v=o==="*"?v*x:v/x}return v};const expr=()=>{let v=term();while(s[i]==="+"||s[i]==="-"){const o=s[i++],x=term();v=o==="+"?v+x:v-x}return v};if(!s)return"";try{const v=expr();return i<s.length||!Number.isFinite(v)?"Error":String(+v.toPrecision(10))}catch(e){return"Error"}}function calcHtml(){const keys=["7","8","9","÷","⌫","4","5","6","×","C","1","2","3","−","(","0",".","=","+",")"];return`<div class="calc-disp" aria-live="polite">${calcE||"0"}${calcAns!==""?`<br><strong>= ${calcAns}</strong>`:""}</div><div class="calc-keys">${keys.map(k=>`<button data-k="${k}" class="${k==="="?"eq":/[0-9.]/.test(k)?"":"op"}">${k}</button>`).join("")}</div><p class="small">Adds, subtracts, multiplies, and divides. It has no fraction or exponent keys.</p>`}function calcBind(body,r){body.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{const k=x.dataset.k;if(k==="C"){calcE="";calcAns=""}else if(k==="⌫"){calcE=calcE.slice(0,-1);calcAns=""}else if(k==="="){calcAns=calcEval()}else{if(calcAns!==""&&calcAns!=="Error"&&/^[+−×÷]/.test(k))calcE=calcAns;else if(calcAns!=="")calcE="";calcAns="";calcE+=k}r()})}const FORM={"6.EE.A.1":["Exponents and order of operations",ul(["An exponent tells how many times to use the base as a factor: 2<sup>4</sup> = 2 × 2 × 2 × 2.","Order of operations: 1. parentheses, 2. exponents, 3. multiply and divide from left to right, 4. add and subtract from left to right."])],"6.EE.A.2c":["Evaluating expressions",ul(["Substitute: put the number in place of the letter.","A number next to a letter means multiply: 4n means 4 × n.","An exponent belongs only to the letter it touches: 3x<sup>2</sup> means 3 × x × x.","Then follow the order of operations: exponents, then multiply and divide, then add and subtract."])],"6.NS.A.1":["Dividing fractions",`<p class="formula">a/b ÷ c/d = a/b × d/c</p>`+ul(["Dividing by a fraction asks: how many of these fit?","Multiply by the reciprocal of the number you divide by.","Change a mixed number to a fraction first: 4 1/2 = 9/2.","Check: answer × the number you divided by = the number you started with."])],"7.NS.A.3":["Signs",ul(["negative × positive = negative","negative ÷ negative = positive","Change a mixed number to a fraction first: 1 1/2 = 3/2."])],"6.G.A.1":["Area",`<p class="formula">Rectangle: A = l × w</p><p class="formula">Parallelogram: A = b × h</p><p class="formula">Triangle: A = 1/2 × b × h</p>`+ul(["The height meets the base at a right angle. A slanted side is not the height.","For other shapes, break them into rectangles and triangles. Find each area, then add.","Area is measured in square units."])],"6.G.A.2":["Volume of a rectangular prism",`<p class="formula">V = l × w × h</p><p class="formula">V = B × h</p>`+ul(["B is the area of the base.","Volume is measured in cubic units."])],"6.RP.A.3":["Rates and percent",`<p class="formula">unit rate = total ÷ number of units</p><p class="formula">percent of a number = (percent ÷ 100) × the number</p>`+ul(["Find the price of one, then multiply for any number.","55 percent means 55 out of every 100."])],"6.SP.B.5":["Summarizing data",ul(["Mean: add every value, then divide by how many values there are.","Median: put the values in order and take the middle one. With an even count, take the halfway point between the two middle values.","Range: the largest value minus the smallest."])],"7.G.B.6":["Area and volume",`<p class="formula">Rectangle: A = l × w</p><p class="formula">Prism: V = l × w × h</p>`+ul(["For a solid made of two prisms, find each volume, then add."])]};function formHtml(st){return st.std.filter(x=>FORM[x]).map(x=>`<h4 style="margin:8px 0 2px">${FORM[x][0]}</h4>${FORM[x][1]}`).join("")}const TOOLS={gloss:{name:"Word help",std:READ_STD.concat(["SL.6.2","W.6.8"]),html:glossHtml},frames:{name:"Sentence frames",std:Object.keys(FR),html:framesHtml},mult:{name:"Multiplication chart",std:MATH_STD,html:multHtml,bind:multBind},form:{name:"Formula sheet",std:Object.keys(FORM),html:formHtml},calc:{name:"Calculator (four-function)",std:["6.EE.A.1","6.EE.A.2c","6.G.A.1","6.G.A.2","6.RP.A.3","6.SP.B.5","6.EE.C.9","7.G.B.6"],html:calcHtml,bind:calcBind}};const SUP_CAVEATS=[{t:"passage",std:READ_STD,msg:"If the text was read to the student, this stop shows listening comprehension, not reading."},{t:"gloss",std:["RL.6.4"],msg:"Word help leaves out the words the Sharp Words questions ask about, so those answers are still the student’s own."},{t:"gloss",std:["W.6.8"],msg:"Word help defines credible, paraphrase, and quote. This stop then shows using those ideas with a reference."},{t:"frames",std:READ_STD.concat(["SL.6.2"]),msg:"Sentence frames give the sentence structure. Rate the evidence and thinking the student supplied."},{t:"frames",std:WRITE_STD.concat(["SL.6.4"]),msg:"Sentence frames supply the order, the linking words, and the closing, so count those checks as supported, not independent."},{t:"mult",std:["6.EE.A.1","6.EE.A.2c"],msg:"The chart gives multiplication facts. The student still has to know what the exponent means and which step comes first."},{t:"calc",std:["6.EE.A.1","6.EE.A.2c"],msg:"These stops check computing with exponents in the right order. With the calculator, rate only whether the student chose the right steps, and note that the arithmetic was supported."},{t:"calc",std:["6.G.A.1","6.G.A.2","7.G.B.6"],msg:"The calculator does the arithmetic. Rate whether the student picked the right measurements and set up each area or volume correctly. It has no fraction keys."},{t:"calc",std:["6.RP.A.3","6.SP.B.5","6.EE.C.9"],msg:"The calculator does the arithmetic. Rate whether the student chose the right operation, set the rate or the mean up correctly, and read the data set correctly."},{t:"form",msg:"The formula sheet gives the formulas and rules for this stop, so the stop shows applying them with a reference, not recall."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:READ_STD.concat(["W.6.8"])}}});
